func sum(xs: Array<Int64> @ local?): Int64 {
    var total = 0
    for (x in xs) { total += x }
    total
}
main() {
    let values = Array<Int64>(3, {i => i + 1}) @ local!
    let plain: Int64 @ ~local = sum(values)
    println(plain)
}

func choose(f: () -> String @ local?): Int64 { 0 }
func invoke(f: (() -> Int64) @ local?): Int64 { f() }
func inspect(f: (String @ local?) -> Int64): Int64 { f("abc") }

func pair(value: (Int64, Bool) @ local?): (Int64, Bool) { value }
func item(value: ?Int64 @ local?): Int64 { value ?? 0 }
main() {
    let fixed: VArray<Int64, $2> @ local! = [3, 4]
    let p: (Int64, Bool) @ local! = (fixed[0], true)
    println(pair(p)[0])
    println(item(Some(fixed[1])))
}

