}

class Label {
    var text: String
    init(text: String) { this.text = text }
    exclave init(this @ local!, text: String @ local!) { this.text = text }
    func size(this @ local?): Int64 { text.size }
}
main() {
    let tag = Label("robot") @ local!
    println(tag.size())
}

var tag: String = "dock"
class Marker {
    demode var name: String
    var value: String
    exclave init(this @ local!, value: String @ local!) {
        this.name = ""
        this.value = value
    }
}
func name(): String {
    let marker = Marker("temporary") @ local!
    marker.name = tag
    marker.name
}
main() { println(name()) }

func sequence(n: Int64): Array<Int64> @ local! {
    exclave { Array<Int64>(n, {i => i * 2}) @ local! }
}
main() {
    let values = sequence(3)
    println(values[2])
}

exclave func replace(values: Array<String> @ local!, value: String @ local!): Unit {
    values[0] = value
}
main() {
    let values: Array<String> @ local! = ["old"]
    replace(values, "new")
    println(values[0])
}

func length(): Int64 {
    let text: String @ local! = "hello"
    let view: String @ local? = text
    @ local? func count(): Int64 { view.size }
    count()
}
main() { println(length()) }

interface Measure { func size(this @ local?): Int64 }
class Counter <: Measure {
    var n: Int64 = 0
    init() {}
    exclave init(this @ local!) {}
    public func size(this @ local?): Int64 { n }
    func reset(this @ local!): Unit { n = 0 }
    prop text: String @ local! { get() { exclave { "counter" } } }
}

struct Coordinate <: Copyable {
    var x: Int64
    init(x: Int64) { this.x = x }
}
func plain<T>(value: T @ local?): T where T <: Copyable { value }
main() {
    let value: Coordinate @ local! = Coordinate(42)
    println(plain(value).x)
}

func exclave(n: Int64): Int64 { n + 1 }
func demode(n: Int64): Int64 { n * 2 }
func local(n: Int64): Int64 { n }
main() { println(local(demode(exclave(20)))) }

func apply(value: Int64, callback: Option<(Int64) -> Int64>): Int64 {
    match (callback) { case Some(f) => f(value); case None => value }
}
func run(callback: Option<Option<() -> Int64>>): Int64 {
    match (callback) { case Some(Some(f)) => f(); case _ => 0 }
}
main() {
    println(apply(10) {x => x + 1})
    println(run {42})
    println(run() {=> 42})
}

type Small = Int32
type Same = Small
type Real = Float64
type Character = Rune
main() {
    let n: Small = Small(21)
    let m: Same = Same(n)
    let x = Real(1.5)
    let r = Character(65)
    println(m)
    println(x)
    println(r)
}

sealed abstract class Result {}
class Found <: Result { let value: Int64; init(n: Int64) { value = n } }
class Missing <: Result {}
func code(value: Result): Int64 {
    match (value) { case hit: Found => hit.value; case _: Missing => 0 }
}
main() { println(code(Found(42))) }

func payload<R>(value: Extern<R>): Any where R <: ForeignRuntime<R> {
    Extern<R>.getPayload(value)
}

import std.concurrent.*
main() {
    let total = threadScope<Int64, Int64> {group =>
        group.launch {7}
        group.launch {11}
        var sum = 0
        for (value in group) { sum += value }
        sum
    }
    println(total)
}
